+function injectLiveReload(html: string): string {
+  const closingBody = html.search(/<\/body\s*>/i);
+  return closingBody === -1 ? `${html}${liveReloadScript}` : `${html.slice(0, closingBody)}${liveReloadScript}${html.slice(closingBody)}`;
